mapper.select:
SELECT c.id AS id, c.content AS content, c.create_time AS createTime, c.parent_id AS parentId, c.content_type AS contentType, u.id AS userId, u.username AS username, (SELECT COUNT(*) FROM comment_like cl WHERE cl.user_id = #{userId} AND cl.comment_id = c.id) AS upvoteFlag, (SELECT COUNT(*) FROM comment_like cl WHERE cl.comment_id = c.id) AS upvoteCount, u.avatar AS avatar, u1.id AS replier_id, u1.username AS replierName, u1.avatar AS replierAvatar FROM comment c LEFT JOIN user u ON u.id = c.commenter_id LEFT JOIN user u1 ON u1.id = c.replier_id
AND c.content_type = #{contentType}
AND c.content like concat('%',#{content},'%')
AND c.create_time BETWEEN #{startTime} AND #{endTime}
ORDER BY c.create_time DESC
LIMIT #{current},#{size}

SELECT COUNT(*)
FROM comment c
WHERE c.content_id = #{contentId}
  AND c.content_type = #{contentType}
